```t
t 1
gate recursion
task modular_sum(s: seq, m: int, k: int) returns (r: bool)
  requires m > 0
  requires k >= 0
  requires k <= len(s)
  ensures r == has_mod_subset(s, m, k)
  decreases k
spec fun has_mod_subset(s: seq, m: int, k: int): bool
  decreases k
= if k == 0 then false
  else if m == 1 then true
  else if k == len(s) then has_mod_subset(s, m, k - 1) or (sum_all(s) % m == 0)
  else has_mod_subset(s[0..len(s)-1], m, k) or has_mod_subset(s[0..len(s)-1], m, k - 1) or (s[len(s)-1] % m == 0)
{
  if k == 0 {
    r := false;
  } else {
    if m == 1 {
      r := true;
    } else {
      if k >= len(s) {
        r := modular_sum(s, m, len(s) - 1) or (sum_of_all(s) % m == 0);
      } else {
        var rest: seq := s[0..len(s)-1];
        var last: int := s[len(s)-1];
        var without_last: bool := modular_sum(rest, m, k);
        var with_last_small: bool := modular_sum(rest, m, k - 1);
        var last_alone: bool := (last % m == 0);
        r := without_last or with_last_small or last_alone;
      }
    }
  }
}
```
